types.example:
agentflow-beta LR
  ask["User question"]@{ shape: input }
  flow research["Research agent"]
    plan["Plan searches"]@{ shape: task }
    search["web_search"]@{ shape: tool }
    notes["Source notes"]@{ shape: refdoc }
    plan --> search
    plan -.- notes
  end
  ok["Enough sources?"]@{ shape: decision }
  answer["Send answer"]@{ shape: action }
  ask --> plan
  search --> ok
  ok -- yes --> answer
  ok -- no --x plan

railroad-beta
  title Signed number
  number = sequence(
    optional(choice(terminal("+"), terminal("-"))),
    oneOrMore(nonterminal("digit")),
    optional(sequence(terminal("."), oneOrMore(nonterminal("digit"))))
  ) ;
  digit = choice(terminal("0"), terminal("9")) ;
